struct PixelStatistics
{
    uint64_t count = 0;

    Color mean = Color::Black();
    Color m2   = Color::Black();

    void AddSample(const Color& x)
    {
        ++count;

        const Color delta =
            x - mean;

        mean +=
            delta /
            static_cast<float>(count);

        const Color delta2 =
            x - mean;

        m2 +=
            delta * delta2;
    }

    Color Variance() const
    {
        if (count < 2)
            return Color::Black();

        return
            m2 /
            static_cast<float>(count - 1);
    }

    Color StandardError() const
    {
        if (count < 2)
            return Color::Black();

        return Sqrt(
            Variance() /
            static_cast<float>(count));
    }
};

BSDFSample SampleIdealGlass(
    Vec3 wo,
    Vec3 n,
    float etaI,
    float etaT,
    RNG& rng)
{
    const float cosTheta =
        std::clamp(
            Dot(wo, n),
            0.0f,
            1.0f);

    const float F =
        FresnelDielectric(
            cosTheta,
            etaI,
            etaT);

    const float eta =
        etaI / etaT;

    const auto wt =
        Refract(
            -wo,
            n,
            eta);

    // Total internal reflection.
    if (!wt)
    {
        return
        {
            .Wi = Reflect(-wo, n),
            .Probability = 1.0f,
            .IsDelta = true,
            .IsTransmission = false
        };
    }

    if (Random01(rng) < F)
    {
        return
        {
            .Wi = Reflect(-wo, n),
            .Probability = F,
            .IsDelta = true,
            .IsTransmission = false
        };
    }

    return
    {
        .Wi = *wt,
        .Probability = 1.0f - F,
        .IsDelta = true,
        .IsTransmission = true
    };
}

